import { DEVICE_PLATFORMS, OAUTH_PROVIDERS, type AppResponse, type DevicePlatform, type OAuthProvider, type SocialAuthDeps } from "./types";

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isValidProvider(value: unknown): value is OAuthProvider {
  return typeof value === "string" && (OAUTH_PROVIDERS as readonly string[]).includes(value);
}

export function isValidPlatform(value: unknown): value is DevicePlatform {
  return typeof value === "string" && (DEVICE_PLATFORMS as readonly string[]).includes(value);
}

export function isValidUuid(value: unknown): boolean {
  return typeof value === "string" && UUID_RE.test(value);
}

export async function handleSocialAuth(body: unknown, deps: SocialAuthDeps): Promise<AppResponse> {
  const input = body as Record<string, unknown> | null | undefined;
  const provider = input?.provider;
  if (!isValidProvider(provider)) {
    return { status: 400, body: { error: `Invalid provider. Must be one of: ${OAUTH_PROVIDERS.join(", ")}` } };
  }
  const token = input?.token;
  if (typeof token !== "string" || !token.trim()) {
    return { status: 400, body: { error: "Token is required" } };
  }
  const nonce = typeof input?.nonce === "string" ? input.nonce : undefined;
  const accessToken = typeof input?.access_token === "string" ? input.access_token : undefined;
  const result = await deps.signInWithIdToken(provider, token.trim(), { nonce, access_token: accessToken });
  if (result.error || !result.session) {
    return { status: 401, body: { error: "Authentication failed" } };
  }

  let device_count: number | undefined;
  const deviceId = typeof input?.device_id === "string" ? input.device_id.trim() : undefined;
  const platform = input?.platform;

  if (deps.devices && isValidUuid(deviceId) && isValidPlatform(platform)) {
    await deps.devices.upsert(result.session.user_id, {
      device_id: deviceId as string,
      platform,
      device_name: typeof input?.device_name === "string" ? input.device_name.trim().slice(0, 255) || undefined : undefined
    });
    device_count = await deps.devices.countByUserId(result.session.user_id);
  }

  return {
    status: 200,
    body: {
      access_token: result.session.access_token,
      refresh_token: result.session.refresh_token,
      expires_in: result.session.expires_in,
      ...(device_count !== undefined && { device_count })
    }
  };
}

