import Redis from "ioredis";
import type { Context, MiddlewareHandler } from "hono";

let redis: Redis | null = null;

function getRedis(): Redis | null {
  if (redis) return redis;
  const url = process.env.REDIS_URL;
  if (!url) return null;
  redis = new Redis(url, { maxRetriesPerRequest: 1, lazyConnect: true });
  redis.on("error", (err) => console.error("[rate-limit] Redis error:", err.message));
  return redis;
}

function getClientIp(c: Context): string | null {
  return (
    c.req.header("cf-connecting-ip") ??
    c.req.header("x-forwarded-for")?.split(",")[0]?.trim() ??
    null
  );
}

export function rateLimit(opts: {
  windowMs: number;
  limit: number;
  prefix: string;
}): MiddlewareHandler {
  return async (c, next) => {
    const client = getRedis();
    if (!client) return next();

    const ip = getClientIp(c);
    if (!ip) return next();

    const key = `${opts.prefix}:${ip}`;
    try {
      const count = await client.incr(key);
      if (count === 1) {
        await client.pexpire(key, opts.windowMs);
      }
      if (count > opts.limit) {
        return c.json({ error: "Too many requests" }, 429);
      }
    } catch {
      // If Redis is down, allow the request through
    }
    await next();
  };
}

export const globalRateLimit = rateLimit({ windowMs: 60_000, limit: 100, prefix: "rl:global" });
export const authRateLimit = rateLimit({ windowMs: 60_000, limit: 10, prefix: "rl:auth" });
export const webhookRateLimit = rateLimit({ windowMs: 60_000, limit: 60, prefix: "rl:webhook" });

