import { Hono } from "hono";
import { handleSocialAuth } from "../lib/api/social-auth";
import { createSupabaseServiceClient } from "../lib/supabase/server";
import { createDeviceStore } from "../lib/supabase/repositories";
import type { OAuthProvider } from "../lib/api/types";

const socialAuthRoute = new Hono();

socialAuthRoute.post("/social", async (c) => {
  const body = await c.req.json().catch(() => null);
  const supabase = createSupabaseServiceClient();
  const result = await handleSocialAuth(body, {
    signInWithIdToken: async (provider: OAuthProvider, token: string, options) => {
      const { data, error } = await supabase.auth.signInWithIdToken({
        provider,
        token,
        nonce: options?.nonce,
        access_token: options?.access_token
      });
      if (error) {
        console.error(`[auth/social] Supabase error: ${error.message}`);
      }
      return {
        session: data.session ? {
          access_token: data.session.access_token,
          refresh_token: data.session.refresh_token,
          expires_in: data.session.expires_in,
          user_id: data.session.user.id
        } : null,
        error: error?.message ?? null
      };
    },
    devices: createDeviceStore()
  });
  return c.json(result.body, result.status as never);
});

export { socialAuthRoute };

