import { describe, expect, it } from "vitest";
import {
  buildRevenueCatPurchaseUrl,
  defaultProductConfig,
  deriveStatus,
  encodeRevenueCatAppUserId,
  getRevenueCatEventId,
  getRevenueCatUserCandidates,
  hashRevenueCatPayload,
  isLocalOrigin,
  mapAllEntitlements,
  mapCustomerInfoToSubscriptionStatus,
  normalizeOrigin,
  parseRuntimeEnv,
  validateOrigin,
  validateRuntimeEnv,
  verifyRevenueCatAuthorization,
  type RuntimeEnv
} from "./index";

const validEnv = {
  APP_ENV: "local",
  APP_ORIGIN: "http://localhost:3001",
  BILLING_MODE: "mock",
  NEXT_PUBLIC_SUPABASE_URL: "http://127.0.0.1:54321",
  NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY: "publishable",
  SUPABASE_SECRET_KEY: "secret",
  REVENUECAT_WEBHOOK_AUTHORIZATION: "Bearer secret",
  REVENUECAT_PURCHASE_LINK_SANDBOX: "https://pay.rev.cat/sandbox",
  REVENUECAT_PURCHASE_LINK_LIVE: ""
};

describe("product helpers", () => {
  it("should normalize origins and provide default config", () => {
    expect(normalizeOrigin("https://example.com/path?x=1#hash")).toBe("https://example.com");
    expect(defaultProductConfig.appOrigin).toBe("http://localhost:3001");
    expect(() => normalizeOrigin("ftp://example.com")).toThrow("Unsupported origin protocol");
  });
});

describe("runtime env", () => {
  it("should parse local defaults and validate production safeguards", () => {
    const env = parseRuntimeEnv(validEnv);
    expect(env.billingMode).toBe("mock");
    expect(isLocalOrigin(env.appOrigin)).toBe(true);

    const production: RuntimeEnv = {
      ...env,
      appEnv: "production",
      billingMode: "mock",
      revenueCatPurchaseLinkLive: "https://pay.rev.cat/sandbox"
    };
    expect(validateRuntimeEnv(production)).toEqual([
      "Production must use revenuecat_live billing mode",
      "Production origins cannot use localhost",
      "Production live purchase link cannot look like a sandbox/test link",
      "Sandbox and live RevenueCat purchase links must differ",
      "CF_VERIFY_SECRET is required in production",
      "REDIS_URL is required in production"
    ]);
  });

  it("should reject invalid, missing, and mismatched env values", () => {
    expect(() => parseRuntimeEnv({ ...validEnv, APP_ENV: "prod" })).toThrow("Unsupported value");
    expect(() => parseRuntimeEnv({ ...validEnv, APP_ORIGIN: "" })).toThrow("Missing required environment value");
    expect(() =>
      parseRuntimeEnv({
        ...validEnv,
        APP_ENV: "production",
        APP_ORIGIN: "https://app.example.com",
        BILLING_MODE: "mock"
      })
    ).toThrow("Production must use revenuecat_live billing mode");
    expect(validateRuntimeEnv({ ...parseRuntimeEnv(validEnv), billingMode: "revenuecat_sandbox", revenueCatPurchaseLinkSandbox: "" })).toContain(
      "RevenueCat sandbox purchase link is required in sandbox billing mode"
    );
    expect(validateRuntimeEnv({ ...parseRuntimeEnv(validEnv), billingMode: "revenuecat_live", revenueCatPurchaseLinkLive: "" })).toContain(
      "RevenueCat live purchase link is required in live billing mode"
    );
    expect(
      validateRuntimeEnv({
        ...parseRuntimeEnv(validEnv),
        appEnv: "production",
        billingMode: "revenuecat_live",
        appOrigin: "https://app.example.com",
        revenueCatPurchaseLinkSandbox: "https://pay.rev.cat/same",
        revenueCatPurchaseLinkLive: "https://pay.rev.cat/same"
      })
    ).toContain("Sandbox and live RevenueCat purchase links must differ");
  });
});

describe("billing helpers", () => {
  it("should encode RevenueCat App User IDs and build purchase URLs", () => {
    expect(encodeRevenueCatAppUserId(" user-123 ")).toBe("user-123");
    expect(buildRevenueCatPurchaseUrl("https://pay.rev.cat/token?package_id=annual", "user 123", "u@example.com")).toBe(
      "https://pay.rev.cat/token/user%20123?package_id=annual&email=u%40example.com"
    );
  });

  it("should reject invalid App User IDs", () => {
    expect(() => encodeRevenueCatAppUserId("")).toThrow("Invalid RevenueCat App User ID");
    expect(() => encodeRevenueCatAppUserId("bad/id")).toThrow("Invalid RevenueCat App User ID");
    expect(() => encodeRevenueCatAppUserId("a".repeat(101))).toThrow("Invalid RevenueCat App User ID");
  });
});

describe("security helpers", () => {
  it("should validate Origin header", () => {
    expect(validateOrigin("http://localhost:3001/path", "http://localhost:3001")).toBe(true);
    expect(validateOrigin("http://evil.test", "http://localhost:3001")).toBe(false);
    expect(validateOrigin(undefined, "http://localhost:3001")).toBe(false);
    expect(validateOrigin("not a url", "http://localhost:3001")).toBe(false);
  });
});

describe("RevenueCat helpers", () => {
  it("should verify webhook auth, event ids, candidates, and hashes", () => {
    const payload = {
      api_version: "1.0",
      event: { id: " event_1 ", app_user_id: "user_a", original_app_user_id: "user_b", aliases: ["user_a", "user_c"] }
    };
    expect(verifyRevenueCatAuthorization("Bearer secret", "Bearer secret")).toBe(true);
    expect(verifyRevenueCatAuthorization("Bearer nope", "Bearer secret")).toBe(false);
    expect(verifyRevenueCatAuthorization("Bearer secret", "")).toBe(false);
    expect(getRevenueCatEventId(payload)).toBe("event_1");
    expect(getRevenueCatEventId({ event: {} })).toBeNull();
    expect(getRevenueCatUserCandidates(payload)).toEqual(["user_a", "user_b", "user_c"]);
    expect(getRevenueCatUserCandidates({ event: { aliases: [""] } })).toEqual([]);
    expect(hashRevenueCatPayload(payload)).toBe(hashRevenueCatPayload(payload));
  });

  it("should map customer info to single-entitlement subscription snapshots", () => {
    const now = new Date("2026-04-21T00:00:00Z");
    expect(mapCustomerInfoToSubscriptionStatus({}, "pro", now)).toMatchObject({ status: "unknown", rawSubscriber: null });
    expect(mapCustomerInfoToSubscriptionStatus({ subscriber: { entitlements: {}, subscriptions: {} } }, "pro", now)).toMatchObject({ status: "none" });
    expect(
      mapCustomerInfoToSubscriptionStatus(
        { subscriber: { entitlements: { pro: { product_identifier: "monthly", expires_date: null } }, subscriptions: { monthly: { store: "stripe" } } } },
        "pro",
        now
      )
    ).toMatchObject({ status: "active", store: "stripe" });
    expect(
      mapCustomerInfoToSubscriptionStatus(
        { subscriber: { entitlements: { pro: { product_identifier: "monthly", grace_period_expires_date: "2026-04-22T00:00:00Z" } }, subscriptions: {} } },
        "pro",
        now
      )
    ).toMatchObject({ status: "grace_period" });
    expect(
      mapCustomerInfoToSubscriptionStatus(
        { subscriber: { entitlements: { pro: { product_identifier: "monthly", expires_date: "2026-04-20T00:00:00Z" } }, subscriptions: {} } },
        "pro",
        now
      )
    ).toMatchObject({ status: "expired" });
    expect(
      mapCustomerInfoToSubscriptionStatus(
        {
          subscriber: {
            entitlements: { pro: { product_identifier: "monthly" } },
            subscriptions: { monthly: { expires_date: "2026-04-22T00:00:00Z", period_type: "trial" } }
          }
        },
        "pro",
        now
      )
    ).toMatchObject({ status: "trialing", renewsAt: "2026-04-22T00:00:00Z" });
    expect(deriveStatus("2026-04-22T00:00:00Z", null, "normal", now)).toBe("active");
  });

  it("should map all entitlements from a subscriber snapshot", () => {
    const now = new Date("2026-04-21T00:00:00Z");
    const customerInfo = {
      subscriber: {
        entitlements: {
          plant_id_pro: { product_identifier: "plant_monthly", expires_date: null },
          bird_id_pro: { product_identifier: "all_apps_bundle", expires_date: "2026-04-22T00:00:00Z" }
        },
        subscriptions: {
          plant_monthly: { store: "app_store" },
          all_apps_bundle: { store: "play_store", period_type: "trial" }
        }
      }
    };
    const entitlements = mapAllEntitlements(customerInfo, now);
    expect(entitlements).toHaveLength(2);
    const plant = entitlements.find((e) => e.entitlementId === "plant_id_pro");
    const bird = entitlements.find((e) => e.entitlementId === "bird_id_pro");
    expect(plant).toMatchObject({ status: "active", store: "app_store", productIdentifier: "plant_monthly" });
    expect(bird).toMatchObject({ status: "trialing", store: "play_store", productIdentifier: "all_apps_bundle" });
  });

  it("should return empty array for missing subscriber data", () => {
    expect(mapAllEntitlements({})).toEqual([]);
    expect(mapAllEntitlements({ subscriber: {} })).toEqual([]);
  });
});

