import { createHash, timingSafeEqual } from "node:crypto";

export interface RevenueCatWebhookPayload {
  api_version?: string;
  event?: {
    id?: string;
    app_user_id?: string;
    original_app_user_id?: string;
    aliases?: string[];
  };
}

export interface RevenueCatCustomerInfo {
  subscriber?: {
    entitlements?: Record<string, {
      expires_date?: string | null;
      grace_period_expires_date?: string | null;
      product_identifier?: string;
    }>;
    subscriptions?: Record<string, {
      store?: string;
      period_type?: string;
      expires_date?: string | null;
    }>;
  };
}

export type SubscriptionStatus = "active" | "trialing" | "grace_period" | "expired" | "none" | "unknown";

export interface SubscriptionStatusSnapshot {
  entitlementId: string;
  status: SubscriptionStatus;
  renewsAt: string | null;
  expiresAt: string | null;
  store: string;
  source: "revenuecat";
  rawSubscriber: RevenueCatCustomerInfo["subscriber"] | null;
}

export function verifyRevenueCatAuthorization(actual: string | null | undefined, expected: string): boolean {
  if (!actual || expected.length === 0) return false;
  const actualBuf = Buffer.from(actual.trim());
  const expectedBuf = Buffer.from(expected);
  if (actualBuf.length !== expectedBuf.length) return false;
  return timingSafeEqual(actualBuf, expectedBuf);
}

export function getRevenueCatEventId(payload: RevenueCatWebhookPayload): string | null {
  return payload.event?.id?.trim() || null;
}

export function getRevenueCatUserCandidates(payload: RevenueCatWebhookPayload): string[] {
  const event = payload.event;
  const values = [event?.app_user_id, event?.original_app_user_id, ...(event?.aliases ?? [])];
  return [...new Set(values.filter((value): value is string => !!value && value.trim().length > 0))];
}

export function hashRevenueCatPayload(payload: unknown): string {
  return createHash("sha256").update(JSON.stringify(payload)).digest("hex");
}

export function mapCustomerInfoToSubscriptionStatus(
  customerInfo: RevenueCatCustomerInfo,
  entitlementId: string,
  now = new Date()
): SubscriptionStatusSnapshot {
  const subscriber = customerInfo.subscriber ?? null;
  const entitlement = subscriber?.entitlements?.[entitlementId];
  if (!subscriber) {
    return { entitlementId, status: "unknown", renewsAt: null, expiresAt: null, store: "unknown", source: "revenuecat", rawSubscriber: null };
  }
  if (!entitlement) {
    return { entitlementId, status: "none", renewsAt: null, expiresAt: null, store: "unknown", source: "revenuecat", rawSubscriber: subscriber };
  }
  const subscription = entitlement.product_identifier ? subscriber.subscriptions?.[entitlement.product_identifier] : undefined;
  const expiresAt = entitlement.expires_date ?? subscription?.expires_date ?? null;
  const graceEndsAt = entitlement.grace_period_expires_date ?? null;
  const store = subscription?.store ?? "unknown";
  const status = deriveStatus(expiresAt, graceEndsAt, subscription?.period_type, now);
  return { entitlementId, status, renewsAt: expiresAt, expiresAt, store, source: "revenuecat", rawSubscriber: subscriber };
}

export interface EntitlementSnapshot {
  entitlementId: string;
  status: SubscriptionStatus;
  expiresAt: string | null;
  productIdentifier: string | null;
  store: string;
}

export function mapAllEntitlements(
  customerInfo: RevenueCatCustomerInfo,
  now = new Date()
): EntitlementSnapshot[] {
  const subscriber = customerInfo.subscriber;
  if (!subscriber?.entitlements) return [];
  return Object.entries(subscriber.entitlements).map(([id, entitlement]) => {
    const subscription = entitlement.product_identifier ? subscriber.subscriptions?.[entitlement.product_identifier] : undefined;
    const expiresAt = entitlement.expires_date ?? subscription?.expires_date ?? null;
    const graceEndsAt = entitlement.grace_period_expires_date ?? null;
    const store = subscription?.store ?? "unknown";
    const status = deriveStatus(expiresAt, graceEndsAt, subscription?.period_type, now);
    return {
      entitlementId: id,
      status,
      expiresAt,
      productIdentifier: entitlement.product_identifier ?? null,
      store
    };
  });
}

export function deriveStatus(
  expiresAt: string | null,
  graceEndsAt: string | null,
  periodType: string | undefined,
  now: Date
): SubscriptionStatus {
  if (graceEndsAt && Date.parse(graceEndsAt) > now.getTime()) return "grace_period";
  if (!expiresAt) return "active";
  if (Date.parse(expiresAt) <= now.getTime()) return "expired";
  return periodType?.toLowerCase() === "trial" ? "trialing" : "active";
}

